-- =============================================================================
-- Vomatt API - Database Schema (single source of truth; spring.jpa.hibernate.ddl-auto=none)
-- Database: PostgreSQL / Schema: vomatt
-- ID: UUID v7, generated by the application's UUIDv7Generator
-- All time columns are TIMESTAMPTZ (mapped to Java OffsetDateTime)
-- =============================================================================

CREATE SCHEMA IF NOT EXISTS vomatt;

-- =============================================================================
-- USERS: OTP / OAuth login, no passwords stored; roles stored as text[] (user / moderator / admin)
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.users (
    id               UUID         PRIMARY KEY,
    username         VARCHAR(50)  NOT NULL UNIQUE,
    email            VARCHAR(254) UNIQUE,
    phone_number     VARCHAR(20)  UNIQUE,
    roles            TEXT[]       NOT NULL DEFAULT ARRAY['user'],
    auth_method      VARCHAR(20),
    avatar_url       VARCHAR(500),
    last_login_at    TIMESTAMPTZ,
    points           INTEGER      NOT NULL DEFAULT 0,
    membership_level VARCHAR(20)  NOT NULL DEFAULT 'BASIC',
    active           BOOLEAN      NOT NULL DEFAULT TRUE,
    first_name       VARCHAR(50),
    last_name        VARCHAR(50),
    location         VARCHAR(100),
    display_name     VARCHAR(100),
    bio              TEXT,
    created_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT chk_users_identifier CHECK (email IS NOT NULL OR phone_number IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS vomatt.user_preferences (
    id               UUID        PRIMARY KEY,
    user_id          UUID        NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    preference_key   VARCHAR(50) NOT NULL,
    preference_value TEXT,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (user_id, preference_key)
);

-- =============================================================================
-- SEARCH: character bigrams of Poll title + description (ADR 0001)
-- The function body is deliberately a single SQL expression with no semicolons, so this file can be split on semicolons and executed
-- =============================================================================
CREATE OR REPLACE FUNCTION vomatt.text_bigrams(input TEXT) RETURNS TEXT[]
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$ SELECT COALESCE(array_agg(DISTINCT substr(lower(input), i, 2)), '{}') FROM generate_series(1, char_length(input) - 1) AS i $$;

-- =============================================================================
-- VOTES
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.votes (
    id                     UUID          PRIMARY KEY,
    title                  VARCHAR(200)  NOT NULL,
    description            VARCHAR(1000),
    creator_id             UUID          NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    vote_type              VARCHAR(20)   NOT NULL DEFAULT 'STANDARD',
    start_time             TIMESTAMPTZ   NOT NULL DEFAULT now(),
    end_time               TIMESTAMPTZ   NOT NULL,
    is_active              BOOLEAN       NOT NULL DEFAULT TRUE,
    allow_multiple_choices BOOLEAN       NOT NULL DEFAULT FALSE,
    is_anonymous           BOOLEAN       NOT NULL DEFAULT FALSE,
    audience               VARCHAR(20)   NOT NULL DEFAULT 'PUBLIC',
    max_choices            INTEGER       NOT NULL DEFAULT 1,
    voter_visibility       VARCHAR(20)   NOT NULL DEFAULT 'OWNER',
    search_bigrams         TEXT[]        GENERATED ALWAYS AS
                           (vomatt.text_bigrams(COALESCE(title, '') || ' ' || COALESCE(description, ''))) STORED,
    created_at             TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at             TIMESTAMPTZ   NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS vomatt.vote_options (
    id            UUID         PRIMARY KEY,
    text          VARCHAR(200) NOT NULL,
    description   VARCHAR(500),
    vote_id       UUID         NOT NULL REFERENCES vomatt.votes (id) ON DELETE CASCADE,
    display_order INTEGER      NOT NULL DEFAULT 0,
    image_url     VARCHAR(500),
    vote_count    INTEGER      NOT NULL DEFAULT 0,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS vomatt.user_votes (
    id         UUID        PRIMARY KEY,
    user_id    UUID        NOT NULL REFERENCES vomatt.users (id)        ON DELETE CASCADE,
    vote_id    UUID        NOT NULL REFERENCES vomatt.votes (id)        ON DELETE CASCADE,
    option_id  UUID        NOT NULL REFERENCES vomatt.vote_options (id) ON DELETE CASCADE,
    ip_address VARCHAR(45),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    -- Polls are single-choice: one Ballot row per user per Poll
    UNIQUE (user_id, vote_id)
);

-- Invitees of an Invite-only Poll: only they and the owner can reach it. Each row is a user or a normalized email
-- not yet tied to a user; verifying that email at sign-up / sign-in turns the row into a user row
CREATE TABLE IF NOT EXISTS vomatt.vote_invitees (
    id         UUID         PRIMARY KEY,
    vote_id    UUID         NOT NULL REFERENCES vomatt.votes (id) ON DELETE CASCADE,
    user_id    UUID         REFERENCES vomatt.users (id) ON DELETE CASCADE,
    email      VARCHAR(254),
    created_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    UNIQUE (vote_id, user_id),
    CONSTRAINT chk_vote_invitees_user_or_email CHECK (num_nonnulls(user_id, email) = 1)
);

-- For RANKING / RATING poll types (Phase 2, no entity / service yet)
CREATE TABLE IF NOT EXISTS vomatt.user_rankings (
    id            UUID        PRIMARY KEY,
    user_id       UUID        NOT NULL REFERENCES vomatt.users (id)        ON DELETE CASCADE,
    vote_id       UUID        NOT NULL REFERENCES vomatt.votes (id)        ON DELETE CASCADE,
    option_id     UUID        NOT NULL REFERENCES vomatt.vote_options (id) ON DELETE CASCADE,
    rank_position INTEGER     NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (user_id, vote_id, option_id)
);

CREATE TABLE IF NOT EXISTS vomatt.user_ratings (
    id         UUID        PRIMARY KEY,
    user_id    UUID        NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    vote_id    UUID        NOT NULL REFERENCES vomatt.votes (id) ON DELETE CASCADE,
    score      INTEGER     NOT NULL CHECK (score BETWEEN 1 AND 5),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (user_id, vote_id)
);

-- =============================================================================
-- COMMENTS
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.vote_comments (
    id         UUID        PRIMARY KEY,
    vote_id    UUID        NOT NULL REFERENCES vomatt.votes (id) ON DELETE CASCADE,
    user_id    UUID        NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    content    TEXT        NOT NULL,
    parent_id  UUID        REFERENCES vomatt.vote_comments (id) ON DELETE CASCADE,
    is_deleted BOOLEAN     NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS vomatt.comment_likes (
    id         UUID        PRIMARY KEY,
    comment_id UUID        NOT NULL REFERENCES vomatt.vote_comments (id) ON DELETE CASCADE,
    user_id    UUID        NOT NULL REFERENCES vomatt.users (id)         ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (comment_id, user_id)
);

-- =============================================================================
-- NOTIFICATIONS: "Poll ended" notifications are derived at read time; only read state is stored (ADR 0003)
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.notification_reads (
    user_id UUID        NOT NULL REFERENCES vomatt.users (id) ON DELETE CASCADE,
    vote_id UUID        NOT NULL REFERENCES vomatt.votes (id) ON DELETE CASCADE,
    read_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, vote_id)
);

-- =============================================================================
-- TAGS
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.tags (
    id            UUID         PRIMARY KEY,
    name          VARCHAR(30)  NOT NULL UNIQUE,
    slug          VARCHAR(50)  NOT NULL UNIQUE,
    description   VARCHAR(200),
    display_order INTEGER      NOT NULL DEFAULT 0,
    usage_count   INTEGER      NOT NULL DEFAULT 0,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS vomatt.vote_tags (
    vote_id UUID NOT NULL REFERENCES vomatt.votes (id) ON DELETE CASCADE,
    tag_id  UUID NOT NULL REFERENCES vomatt.tags (id)  ON DELETE RESTRICT,
    PRIMARY KEY (vote_id, tag_id)
);

-- =============================================================================
-- LOOKUP (dictionary tables)
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.lookup (
    id             UUID         PRIMARY KEY,
    lookup_type    VARCHAR(50)  NOT NULL,
    lookup_key     VARCHAR(50)  NOT NULL,
    lookup_value   JSON         NOT NULL,
    seq            INT          NOT NULL DEFAULT 0,
    parent_type    VARCHAR(50),
    parent_key     VARCHAR(50),
    is_active      BOOLEAN      NOT NULL DEFAULT TRUE,
    description    VARCHAR(100),
    frontend_using BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uk_lookup_type_key UNIQUE (lookup_type, lookup_key)
);

-- =============================================================================
-- AUDIT_LOGS: no FK on purpose, so audit records survive user deletion
-- =============================================================================
CREATE TABLE IF NOT EXISTS vomatt.audit_logs (
    id            UUID         PRIMARY KEY,
    user_id       VARCHAR(36),
    username      VARCHAR(254),
    action        VARCHAR(50)  NOT NULL,
    resource_type VARCHAR(50)  NOT NULL,
    resource_id   VARCHAR(36),
    ip_address    VARCHAR(45),
    user_agent    TEXT,
    request_uri   VARCHAR(500),
    http_method   VARCHAR(10),
    success       BOOLEAN      NOT NULL DEFAULT TRUE,
    error_message TEXT,
    details       TEXT,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- =============================================================================
-- INDEXES (UNIQUE columns already have an index; not duplicated here)
-- =============================================================================
CREATE INDEX IF NOT EXISTS idx_votes_creator_start_id      ON vomatt.votes (creator_id, start_time DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_votes_start_id              ON vomatt.votes (start_time DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_votes_end_id                ON vomatt.votes (end_time, id);
CREATE INDEX IF NOT EXISTS idx_vote_options_vote_order     ON vomatt.vote_options (vote_id, display_order);
CREATE INDEX IF NOT EXISTS idx_user_votes_vote_option      ON vomatt.user_votes (vote_id, option_id);
CREATE INDEX IF NOT EXISTS idx_user_votes_vote_created     ON vomatt.user_votes (vote_id, created_at, id);
CREATE INDEX IF NOT EXISTS idx_vote_invitees_user_id       ON vomatt.vote_invitees (user_id);
CREATE INDEX IF NOT EXISTS idx_user_rankings_vote_id       ON vomatt.user_rankings (vote_id);
CREATE INDEX IF NOT EXISTS idx_user_ratings_vote_id        ON vomatt.user_ratings (vote_id);
CREATE INDEX IF NOT EXISTS idx_vote_comments_vote_created  ON vomatt.vote_comments (vote_id, created_at) WHERE is_deleted = FALSE;
CREATE INDEX IF NOT EXISTS idx_vote_comments_user_id       ON vomatt.vote_comments (user_id);
CREATE INDEX IF NOT EXISTS idx_comment_likes_user_id       ON vomatt.comment_likes (user_id);
CREATE INDEX IF NOT EXISTS idx_tags_usage_count            ON vomatt.tags (usage_count DESC);
CREATE INDEX IF NOT EXISTS idx_vote_tags_tag_id            ON vomatt.vote_tags (tag_id);
CREATE INDEX IF NOT EXISTS idx_lookup_type_active          ON vomatt.lookup (lookup_type, is_active);
CREATE INDEX IF NOT EXISTS idx_lookup_parent               ON vomatt.lookup (parent_type, parent_key);
CREATE INDEX IF NOT EXISTS idx_lookup_frontend             ON vomatt.lookup (frontend_using, is_active);
CREATE INDEX IF NOT EXISTS idx_audit_logs_user_id          ON vomatt.audit_logs (user_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_resource         ON vomatt.audit_logs (resource_type, resource_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_created_at       ON vomatt.audit_logs (created_at);

-- =============================================================================
-- UPGRADES: add columns to existing databases (idempotent; no-op on a fresh database)
-- =============================================================================
-- Option vote count (atomically adjusted when Ballots are written; see db/reconcile-vote-counts.sql to reconcile)
ALTER TABLE vomatt.vote_options ADD COLUMN IF NOT EXISTS vote_count INTEGER NOT NULL DEFAULT 0;
-- Every Poll must have an end time (production had 0 Polls at launch, so no backfill needed)
ALTER TABLE vomatt.votes ALTER COLUMN end_time SET NOT NULL;
-- Voter visibility: NOBODY / OWNER (default) / SIGNED_IN; cannot change after the Poll starts
ALTER TABLE vomatt.votes ADD COLUMN IF NOT EXISTS voter_visibility VARCHAR(20) NOT NULL DEFAULT 'OWNER';
-- Generated bigram column for search (not mapped to the entity) and its GIN index; the index must be created after the column is added
ALTER TABLE vomatt.votes ADD COLUMN IF NOT EXISTS search_bigrams TEXT[] GENERATED ALWAYS AS
    (vomatt.text_bigrams(COALESCE(title, '') || ' ' || COALESCE(description, ''))) STORED;
CREATE INDEX IF NOT EXISTS idx_votes_search_bigrams ON vomatt.votes USING GIN (search_bigrams);
-- Delete (soft): a Deleted Poll is hidden from everyone, owner included; the row and its Ballots are kept
ALTER TABLE vomatt.votes ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;
-- Audience: PUBLIC (default) / UNLISTED / INVITE_ONLY; replaces the never-used is_public, which old databases keep unmapped
ALTER TABLE vomatt.votes ADD COLUMN IF NOT EXISTS audience VARCHAR(20) NOT NULL DEFAULT 'PUBLIC';
-- Deadline: the end time the owner set; ending early moves only end_time (ADR 0004).
-- Backfilled from end_time, so Polls that ended early before this column get the moment they Ended
ALTER TABLE vomatt.votes ADD COLUMN IF NOT EXISTS deadline TIMESTAMPTZ;
UPDATE vomatt.votes SET deadline = end_time WHERE deadline IS NULL;
ALTER TABLE vomatt.votes ALTER COLUMN deadline SET NOT NULL;
-- Turnout (Participants) for Top: atomically adjusted with option counts; backfilled here, reconciled by db/reconcile-vote-counts.sql
ALTER TABLE vomatt.votes ADD COLUMN IF NOT EXISTS turnout INTEGER NOT NULL DEFAULT 0;
UPDATE vomatt.votes v SET turnout = c.actual
FROM (SELECT v2.id, COUNT(uv.id) AS actual
      FROM vomatt.votes v2 LEFT JOIN vomatt.user_votes uv ON uv.vote_id = v2.id
      GROUP BY v2.id) c
WHERE c.id = v.id AND v.turnout <> c.actual;
CREATE INDEX IF NOT EXISTS idx_votes_turnout_start_id ON vomatt.votes (turnout DESC, start_time DESC, id DESC);
-- Comment replies (one level): parent_id only points to top-level comments
ALTER TABLE vomatt.vote_comments ADD COLUMN IF NOT EXISTS parent_id UUID REFERENCES vomatt.vote_comments (id) ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS idx_vote_comments_parent ON vomatt.vote_comments (parent_id, created_at, id);
-- Email Invitees: user_id becomes optional, exactly one of user_id / email is set, one row per Poll + email.
-- The email index serves binding at sign-up / sign-in
ALTER TABLE vomatt.vote_invitees ALTER COLUMN user_id DROP NOT NULL;
ALTER TABLE vomatt.vote_invitees ADD COLUMN IF NOT EXISTS email VARCHAR(254);
ALTER TABLE vomatt.vote_invitees DROP CONSTRAINT IF EXISTS chk_vote_invitees_user_or_email;
ALTER TABLE vomatt.vote_invitees ADD CONSTRAINT chk_vote_invitees_user_or_email CHECK (num_nonnulls(user_id, email) = 1);
CREATE UNIQUE INDEX IF NOT EXISTS uk_vote_invitees_vote_email ON vomatt.vote_invitees (vote_id, email) WHERE email IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_vote_invitees_email ON vomatt.vote_invitees (email) WHERE email IS NOT NULL;
-- One Ballot row per user per Poll (was UNIQUE (user_id, vote_id, option_id)).
-- A DO block is atomic: if duplicates make the CREATE fail, the old constraint and index stay even when psql
-- continues past errors. To dedup first, keep the latest row per (user_id, vote_id), then run reconcile-vote-counts.sql:
--   DELETE FROM vomatt.user_votes a USING vomatt.user_votes b
--   WHERE a.user_id = b.user_id AND a.vote_id = b.vote_id AND a.id < b.id;
DO $$
BEGIN
    CREATE UNIQUE INDEX IF NOT EXISTS user_votes_user_id_vote_id_key ON vomatt.user_votes (user_id, vote_id);
    ALTER TABLE vomatt.user_votes DROP CONSTRAINT IF EXISTS user_votes_user_id_vote_id_option_id_key;
    -- Prefix of the new unique index
    DROP INDEX IF EXISTS vomatt.idx_user_votes_user_vote;
END $$;
-- Redundant indexes: prefixes of other indexes, or low-selectivity columns no query filters on
DROP INDEX IF EXISTS vomatt.idx_votes_creator_id;
DROP INDEX IF EXISTS vomatt.idx_users_active;
DROP INDEX IF EXISTS vomatt.idx_votes_vote_type;
DROP INDEX IF EXISTS vomatt.idx_votes_active_time;
